// Dibuja solo los píxeles de la receta que cumplen dentro(x, y, c).
// desplaza(x, y) devuelve cuánto baja ese píxel (para torcer las alas).
function trozo(dentro, desplaza = () => 0) {
  const px = (x, y, c) => { if (dentro(x, y, c)) set_pixel(x, y + desplaza(x, y), c); };
  receta(px, (x, y, w, h, c) => {
    for (let j = y; j < y + h; j++)
      for (let i = x; i < x + w; i++) px(i, j, c);
  });
}

const en_elipse = (x, y, cx, cy, rx, ry) => ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1;
const es_rojo = (c) => {
  const r = parseInt(c.slice(1, 3), 16), g = parseInt(c.slice(3, 5), 16);
  return r > 100 && r > g * 2;
};

// Regiones (en orden de prioridad): núcleo, abdomen, cabeza con cañones, placas y alas.
const zona_nucleo = (x, y) => en_elipse(x, y, 96, 74, 14, 17);
const zona_abdomen = (x, y) => !zona_nucleo(x, y) && en_elipse(x, y, 96, 29, 26, 27);
const zona_cabeza = (x, y) =>
  !zona_nucleo(x, y) && !zona_abdomen(x, y) &&
  (en_elipse(x, y, 97, 114, 35, 20) || (y >= 100 && ((x >= 44 && x <= 66) || (x >= 126 && x <= 148))));
const zona_placas = (x, y) =>
  !zona_nucleo(x, y) && !zona_abdomen(x, y) && !zona_cabeza(x, y) && en_elipse(x, y, 96, 74, 39, 25);
const zona_cuerpo = (x, y) => zona_nucleo(x, y) || zona_abdomen(x, y) || zona_cabeza(x, y) || zona_placas(x, y);
const zona_visor = (x, y, c) => x >= 74 && x <= 119 && y >= 106 && y <= 118 && es_rojo(c);

// Alas: la punta baja `punta` píxeles y la raíz (junto al cuerpo) no se mueve.
// Si se mueve, la parte cercana a la raíz se dibuja también quieta debajo para que no se abran huecos junto al cuerpo.
part("ala_izq", ({ punta = 0 }) => {
  if (punta != 0) trozo((x, y) => x >= 44 && x < 96 && !zona_cuerpo(x, y));
  trozo((x, y) => x < 96 && !zona_cuerpo(x, y),
    (x) => Math.round(punta * clamp((78 - x) / 60, 0, 1)));
});
part("ala_der", ({ punta = 0 }) => {
  if (punta != 0) trozo((x, y) => x >= 96 && x <= 148 && !zona_cuerpo(x, y));
  trozo((x, y) => x >= 96 && !zona_cuerpo(x, y),
    (x) => Math.round(punta * clamp((x - 114) / 60, 0, 1)));
});
part("abdomen", () => trozo(zona_abdomen));
part("cabeza", () => trozo(zona_cabeza));
part("placa_izq", () => trozo((x, y) => x < 96 && zona_placas(x, y)));
part("placa_der", () => trozo((x, y) => x >= 96 && zona_placas(x, y)));
part("nucleo", () => trozo(zona_nucleo));

// Visor apagado: sus rojos pasan a rojo oscuro.
part("visor_apagado", () => {
  const px = (x, y, c) => { if (zona_visor(x, y, c)) set_pixel(x, y, "#8c0c1f"); };
  receta(px, (x, y, w, h, c) => {
    for (let j = y; j < y + h; j++)
      for (let i = x; i < x + w; i++) px(i, j, c);
  });
});

// Núcleo expuesto: hueco oscuro detrás de las placas, núcleo 1 px más grande y brillo central.
part("hueco", ({ abre = 0 }) => {
  ellipse(96, 74, 14 + abre, 17, "#13300e");
});
part("nucleo_vivo", ({ brillo = 0 }) => {
  ellipse(96, 74, 13, 16, "#ac2029");
  ellipse(96, 74, 12, 15, "#cb1e30");
  trozo((x, y, c) => zona_nucleo(x, y) && es_rojo(c));
  if (brillo >= 1) ellipse(96, 73, 6, 7, "#ff8a95");
  if (brillo >= 1) ellipse(96, 72, 3, 4, "#ffd6da");
  if (brillo >= 2) ellipse(96, 72, 1, 2, "#ffffff");
});

part("base", () => {
  draw("ala_izq");
  draw("ala_der");
  draw("abdomen");
  draw("cabeza");
  draw("placa_izq");
  draw("placa_der");
  draw("nucleo");
});

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("base");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("aleteo", { frames: 4, fps: 12, loop: true }, (f, { t }) => {
  const punta = [0, -3, -1, 2][f];
  const bote = [0, 1, 1, 0][f];
  move(0, bote, () => {
    draw("ala_izq", { punta });
    draw("ala_der", { punta });
    draw("abdomen");
    draw("cabeza");
    draw("placa_izq");
    draw("placa_der");
    draw("nucleo");
  });
});

action("nucleo", { frames: 6, fps: 10, loop: false }, (f, { t }) => {
  const abre = [0, 1, 2, 3, 3, 3][f];
  const brillo = [0, 0, 1, 1, 2, 2][f];
  draw("ala_izq");
  draw("ala_der");
  draw("abdomen");
  draw("cabeza");
  if (f % 2 == 1) draw("visor_apagado");
  if (f == 0) {
    draw("placa_izq");
    draw("placa_der");
    draw("nucleo");
    return;
  }
  // Las placas en su sitio tapan los huecos que dejan al abrirse por arriba y por abajo.
  draw("placa_izq");
  draw("placa_der");
  draw("hueco", { abre });
  move(-abre, 0, () => draw("placa_izq"));
  move(abre, 0, () => draw("placa_der"));
  draw("nucleo_vivo", { brillo });
});

